def update_centroids(points: list[list[float]], labels: list[int],
                     centroids: list[list[float]]) -> list[list[float]]:
    """Mean of the points assigned to each cluster; an empty cluster keeps its previous centre."""
    k: int = len(centroids)
    dims: int = len(centroids[0])
    sums: list[list[float]] = []
    counts: list[int] = []
    for c in range(k):
        zero: list[float] = []
        for t in range(dims):
            zero.append(0.0)
        sums.append(zero)
        counts.append(0)
    for i in range(len(points)):
        c = labels[i]
        counts[c] += 1
        for t in range(dims):
            sums[c][t] += points[i][t]
    out: list[list[float]] = []
    for c in range(k):
        row: list[float] = []
        for t in range(dims):
            if counts[c] > 0:
                row.append(sums[c][t] / counts[c])
            else:
                row.append(centroids[c][t])
        out.append(row)
    return out

